<?php require_once __DIR__.'/../functions.php'; init_db(); if(logged_in())redirect('index.php');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$r=one('SELECT * FROM admins WHERE username=?',[trim($_POST['username']??'')]);if($r&&password_verify($_POST['password']??'',$r['password_hash'])){$_SESSION['admin_id']=$r['id'];$_SESSION['admin_user']=$r['username'];redirect('index.php');}$err='Benutzername oder Passwort ist nicht korrekt.';}?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Young Images – Login</title><link rel="stylesheet" href="../css/admin.css"></head><body><main class="login"><img src="../assets/young-images-logo.png" class="admin-logo"><h1>Young Images CMS</h1><p>Redaktionsbereich</p><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Benutzername<input name="username" required></label><label>Passwort<input type="password" name="password" required></label><button>Einloggen</button></form></main></body></html>
